#!/usr/bin/env python3
"""Write macos/Flutter/ephemeral/Sparkle.xcconfig for the macOS build."""

import argparse
import base64
import binascii
import os
import re
import sys
import urllib.parse
from pathlib import Path

FEED_URL_ENV = "MACOS_SPARKLE_FEED_URL"
PUBLIC_KEY_ENV = "MACOS_SPARKLE_PUBLIC_KEY"

DISALLOWED_URL_CHARS = re.compile(r"[\s\x00-\x1f\x7f\"'`\\$]")


def repo_root() -> Path:
    return Path(__file__).resolve().parent.parent.parent


def default_output() -> Path:
    return repo_root() / "macos" / "Flutter" / "ephemeral" / "Sparkle.xcconfig"


def escape_xcconfig_value(raw: str) -> str:
    # `//` starts a comment even in values; `/$()` keeps slashes and expands back exactly.
    return raw.replace("/", "/$()")


def validate_feed_url(raw: str) -> str:
    if not raw:
        raise ValueError("feed URL is empty")
    try:
        raw.encode("ascii")
    except UnicodeEncodeError:
        raise ValueError("feed URL must be ASCII")
    if DISALLOWED_URL_CHARS.search(raw):
        raise ValueError("feed URL contains whitespace, control or shell/xcconfig quoting characters")
    parsed = urllib.parse.urlsplit(raw)
    if parsed.scheme.lower() != "https":
        raise ValueError("feed URL must use https")
    if not parsed.hostname:
        raise ValueError("feed URL has no host")
    if parsed.username or parsed.password:
        raise ValueError("feed URL must not embed credentials")
    return raw


def validate_public_key(raw: str) -> str:
    if not raw:
        raise ValueError("public key is empty")
    try:
        decoded = base64.b64decode(raw, validate=True)
    except (binascii.Error, ValueError):
        raise ValueError("public key is not valid base64")
    if len(decoded) != 32:
        raise ValueError(
            f"public key decodes to {len(decoded)} bytes, expected 32"
        )
    return raw


def render_xcconfig(feed_url: str, public_key: str) -> str:
    lines = ["// Generated by configure_macos_sparkle.py; do not edit."]
    if not feed_url and not public_key:
        lines.append("// Sparkle updates disabled: no feed URL or public key.")
    lines.append(f"SPARKLE_FEED_URL = {escape_xcconfig_value(feed_url)}")
    lines.append(f"SPARKLE_PUBLIC_KEY = {escape_xcconfig_value(public_key)}")
    enabled = "YES" if feed_url and public_key else "NO"
    lines.append(f"SPARKLE_REQUIRE_SIGNED_FEED = {enabled}")
    lines.append(f"SPARKLE_VERIFY_UPDATE_BEFORE_EXTRACTION = {enabled}")
    return "\n".join(lines) + "\n"


def resolve_inputs(args: argparse.Namespace) -> tuple[str, str]:
    feed = args.feed_url if args.feed_url is not None else os.environ.get(FEED_URL_ENV) or ""
    key = args.public_key if args.public_key is not None else os.environ.get(PUBLIC_KEY_ENV) or ""
    return feed, key


def write_config(output: Path, content: str) -> None:
    output.parent.mkdir(parents=True, exist_ok=True)
    tmp = output.with_suffix(".xcconfig.tmp")
    tmp.write_text(content, encoding="utf-8")
    os.replace(tmp, output)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Write the macOS Sparkle build configuration.",
    )
    parser.add_argument("--feed-url", default=None,
                        help=f"appcast URL (or {FEED_URL_ENV})")
    parser.add_argument("--public-key", default=None,
                        help=f"base64 Ed25519 public key (or {PUBLIC_KEY_ENV})")
    parser.add_argument("--output", type=Path, default=None,
                        help="override the xcconfig path (default: macos/Flutter/ephemeral/Sparkle.xcconfig)")
    args = parser.parse_args(argv)
    feed, key = resolve_inputs(args)
    output = args.output or default_output()
    try:
        if not feed and not key:
            write_config(output, render_xcconfig("", ""))
            print(f"Sparkle updates disabled ({output})")
            return 0
        if not feed or not key:
            parser.error("feed URL and public key must be set together; "
                         "pass neither to disable updates")
        validate_feed_url(feed)
        validate_public_key(key)
    except ValueError as error:
        parser.error(str(error))
    write_config(output, render_xcconfig(feed, key))
    print(f"Sparkle updates configured: feed {feed} ({output})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
